mapper.select:
SELECT s.surgery_id, s.record_id, s.pet_id, s.client_id, s.doctor_id, s.surgery_name, s.surgery_type, s.anesthesia_type, s.scheduled_time, s.start_time, s.end_time, s.surgeon, s.assistant, s.status, s.fee, s.create_time, p.pet_name, c.client_name, d.doctor_name, m.diagnosis FROM surgery s LEFT JOIN pet p ON s.pet_id = p.pet_id LEFT JOIN client c ON s.client_id = c.client_id LEFT JOIN doctor d ON s.doctor_id = d.doctor_id LEFT JOIN medical_record m ON s.record_id = m.record_id WHERE s.is_del = 0
AND s.status = #{status}
ORDER BY s.scheduled_time ASC, s.surgery_id DESC
